internal val COUNTRY_NAMES_SHN: String =
    "root\u001FAD\u001Dဢႅၼ်ႇတူဝ်ႇရႃႇ\u001EAE\u001Dမိူင်းႁူမ်ႈတုမ် ၸဝ်ႈၾႃႉ ဢႃႇရၢပ်ႈ\u001EAF\u001Dဢႃႇၾၵၢၼ်ႇၼီႇသတၢၼ်ႇ\u001EAG\u001Dဢႅၼ်ႇထီႇၵႂႃႇ လႄႈ ပႃႇပူးတႃႇ\u001EAI\u001Dဢႅၼ်ႇၵုၺ်ႇလႃႇ\u001EAL\u001Dဢႃႇပႃးၼီးယႃး\u001EAM\u001Dဢႃႇမေးၼီးယႃး\u001EAO\u001Dဢႅၼ်ႇၵူဝ်ႇလႃႇ\u001EAQ\u001Dဢႅၼ်ႇတၢၵ်ႈတီးၵႃႈ\u001EAR\u001Dဢႃႇၵျႅၼ်ႇတီးၼႃး\u001EAS\u001Dသႃႇမူဝ်းဝႃႇ ၶွ​င် ဢမႄႇရိၵၢၼ်ႇ\u001EAT\u001Dဢေႃးသထရီးယႃး\u001EAU\u001Dဢေႃႉသထရေးလီးယႃး\u001EAW\u001Dဢႃႇရူးပႃး\u001EAX\u001Dမူႇၵုၼ် ဢေႃးလႅၼ်ႇ\u001EAZ\u001Dဢႃႇၸႃႇပၢႆႇၸၼ်ႇ\u001EBA\u001Dပေႃးသၼီးယႃး လႄႈ ႁႃႇၸီႇၵူဝ်းဝီးၼႃး\u001EBB\u001Dပႃးပေႇတူတ်ႈ\u001EBD\u001Dပင်းၵလႃးတဵတ်ႈ\u001EBE\u001Dပႄႇၵျီႇယမ်ႇ\u001EBF\u001Dပူႇၵီႇၼႃးၾႃးသူဝ်ႇ\u001EBG\u001Dပူႇၵႃႇရီႇယႃႇ\u001EBH\u001Dပႃႇရဵၼ်း\u001EBI\u001Dပူႇရုၼ်းတီႇ\u001EBJ\u001Dပႄႇၼိၼ်း\u001EBL\u001Dသဵင်ႉပႃႇထႄးလႄႇမီႇ\u001EBM\u001Dပႃႇမိဝ်းတႃး\u001EBN\u001Dပရူႇၼၢႆး\u001EBO\u001Dပူဝ်ႇလီးပီးယႃး\u001EBQ\u001Dၼႄႇတႃႇလႅၼ်ႇ တီႈ ၶႃႇရိပ်ႈပီႇယၼ်ႇ\u001EBR\u001Dပရႃႇၸီး\u001EBS\u001Dပႃႇႁႃးမႃး\u001EBT\u001Dၽူႇတၢၼ်ႇ\u001EBV\u001Dမူႇၵုၼ် ပူးဝႅတ်ႉ\u001EBW\u001Dပွတ်ႉသဝႃႇၼႃႇ\u001EBY\u001Dပႄႇလႃႇရုတ်ႈ\u001EBZ\u001Dပႄႇလိတ်ႈ\u001ECA\u001Dၶႅၼ်ႇၼေႇတႃႇ\u001ECC\u001Dမူႇၵုၼ် ၶူဝ်းၵတ်ႉ (ၶီးလိင်း)\u001ECD\u001Dၶွင်ႇၵူဝ်ႇ - ၶိၼ်သျႃးသႃႇ\u001ECF\u001Dမိူင်းႁူမ်ႈပွင်လူၺ်ႈၵူၼ်းလၢႆ ဢႃႇၾရိၵ ပွတ်းၵၢင်\u001ECG\u001Dၶွင်ႇၵူဝ်ႇ - ပရႃၸဝီးလ်\u001ECH\u001Dသဝိတ်ႈၸႃႇလႅၼ်ႇ\u001ECI\u001Dဢၢႆႇဝူဝ်ႇရီႇၶူတ်ႈ\u001ECK\u001Dမူႇၵုၼ် ၶုၵ်ႈ\u001ECL\u001Dၶျီႇလီႇ\u001ECM\u001Dၶႅမ်းမႃးရုၼ်း\u001ECN\u001Dၶႄႇ\u001ECO\u001Dၵူဝ်ႇလမ်ႇပီႇယႃႇ\u001ECR\u001Dၵေႃးသတႃႇရိၵႃႇ\u001ECU\u001Dၵူးပႃး\u001ECV\u001Dၶဵပ်ႉဝႄႇတီႇ\u001ECW\u001Dၵူးရႃႇသၢဝ်ႇ\u001ECX\u001Dၵုၼ်ၶရိတ်ႉသမၢတ်ႉ\u001ECY\u001Dသၢႆႉပရႅတ်ႈ\u001ECZ\u001Dၶျႅၵ်ႈ\u001EDE\u001Dၵျႃႇမၼီႇ\u001EDJ\u001Dၵျီႇပူးတီႇ\u001EDK\u001Dတႅၼ်းမၢၵ်ႈ\u001EDM\u001Dတူဝ်ႇမီႇၼိၵ\u001EDO\u001Dတူဝ်ႇမီႇၼီႇၵၼ်ႇ\u001EDZ\u001Dဢႄးၵျီးရီးယႃး\u001EEC\u001Dဢေႇၵႂႃႇတေႃႇ\u001EEE\u001Dဢႄႇသတူဝ်းၼီးယႃး\u001EEG\u001Dဢီးၵျိပ်ႈ\u001EEH\u001Dသႃႇႁႃႇရႃႇ ပွတ်းတူၵ်း\u001EER\u001Dဢႄႇရီႇထရီးယႃး\u001EES\u001Dသပဵၼ်ႇ\u001EET\u001Dဢီႇတီႇယူဝ်းပီးယႃး\u001EFI\u001Dၾိၼ်ႇလႅၼ်ႇ\u001EFJ\u001Dၾီႇၵျီႇ\u001EFK\u001Dမူႇၵုၼ် ၾွၵ်ႉလႅၼ်ႇ\u001EFM\u001Dၼႃႈလိၼ် မၢႆႇၶရူဝ်ႇၼေးသျၼ်း\u001EFO\u001Dမူႇၵုၼ် ၾႄးရူဝ်း\u001EFR\u001Dၾရၢင်ႇသဵတ်ႈ\u001EGA\u001Dၵႄးပုၼ်ႇ\u001EGB\u001Dမိူင်းႁူမ်ႈတုမ်ႁေႃၶမ်း ပရိတ်ႈတဵၼ်ႇ\u001EGD\u001Dၵရႄႇၼႃႇတႃႇ\u001EGE\u001Dၵျေႃႇၵျႃႇ\u001EGF\u001Dၵုၺ်ႇယႃႇၼႃႇ ၶွင် ၾရၢင်ႇသဵတ်ႈ\u001EGG\u001Dၵႂၢၼ်းသီ\u001EGH\u001Dၵႃႇၼႃႇ\u001EGI\u001Dၵျီႇပရေႃးတႃး\u001EGL\u001Dၵရိၼ်းလႅၼ်း\u001EGM\u001Dၵမ်ႇပီးယႃး\u001EGN\u001Dၵီးၼီး\u001EGP\u001Dၵႂႃးတီႇလုပ်ႈ\u001EGQ\u001Dဢီႇၵူၺ်ႇတေႃႇရီႇယႃႇ ၵီးၼီး\u001EGR\u001Dၵရိတ်ႈ\u001EGS\u001Dၵျေႃႇၵျႃႇ ပွတ်းၸၢၼ်း လႄႈ မူႇၵုၼ် သၢၼ်းဝိတ်ႉ ပွတ်းၸၢတ်း\u001EGT\u001Dၵႂႃႇတမႃႇလႃႇ\u001EGU\u001Dၵႂၢမ်ႇ\u001EGW\u001Dၵီးၼီး-ပိတ်ႈသၢဝ်ႇ\u001EGY\u001Dၵၢႆႇယႃးၼႃႇ\u001EHK\u001Dႁွင်းၵွင်း ၼႃႈလိၵ်ႈဢုပ်ႉပိူင်ႇၶိုၵ်ႉတွၼ်း ၶႄႇ\u001EHM\u001Dမူႇၵုၼ် ႁိူတ်ႉ လႄႈ မူႇၵုၼ် မႅၵ်ႇတေႃႇၼႄႇ\u001EHN\u001Dႁွၼ်ႇတူးရႅတ်ႈ\u001EHR\u001Dၶရူဝ်ႇဢေးသျႃး\u001EHT\u001Dႁေးတီႇ\u001EHU\u001Dႁၢင်ႇၵေႇရီႇ\u001EID\u001Dဢိၼ်ႇတူဝ်ႇၼီးသျႃး\u001EIE\u001Dဢၢႆႇယႃႇလႅၼ်ႇ\u001EIL\u001Dဢိတ်ႇသရေး\u001EIM\u001Dၵုၼ်မႅၼ်း\u001EIN\u001Dဢိၼ်းတီးယႃး\u001EIO\u001Dၼႃႈလိၼ် သမုၵ်ႉတရႃႇဢိၼ်းတီးယႃး ၶွင် ဢိင်းၵလဵတ်ႈ\u001EIQ\u001Dဢီႇရၢၵ်ႈ\u001EIR\u001Dဢီႇရၢၼ်း\u001EIS\u001Dဢၢႆးသလႅၼ်ႇ\u001EIT\u001Dဢီႇတႃႇလီႇ\u001EJE\u001Dၵျႃႇသီႇ\u001EJM\u001Dၵျႃႇမေႇၵႃႇ\u001EJO\u001Dၵျေႃႇတၼ်ႇ\u001EJP\u001Dၵျႃႇပၢၼ်ႇ\u001EKE\u001Dၶႅၼ်ႇၺႃႇ\u001EKG\u001Dၵႃႇၵိတ်ႈသတၼ်ႇ\u001EKH\u001Dၵမ်ႇပေႃးတီးယႃး\u001EKI\u001Dၵိရိပတီႇ\u001EKM\u001Dၶူဝ်ႇမူဝ်ႇရူတ်ႈ\u001EKN\u001Dသဵင်ႉၶိတ်ႈ လႄႈ ၼႄးဝိတ်ႈ\u001EKP\u001Dၵၢဝ်းလီႁွင်ႇ\u001EKR\u001Dၵၢဝ်းလီၸၢၼ်း\u001EKW\u001Dၶူႇဝဵတ်ႈ\u001EKY\u001Dမူႇၵုၼ် ၶေးမႅၼ်း\u001EKZ\u001Dၵႃႇၸၢၵ်ႈသတၼ်ႇ\u001ELA\u001Dလၢဝ်း\u001ELB\u001Dလႄႇပႃႇၼွၼ်ႇ\u001ELC\u001Dသဵင်ႉလူႉသျႃႇ\u001ELI\u001Dလိၵ်ႈတိၼ်ႇသတၢႆႇ\u001ELK\u001Dသီႇရိလင်းၵႃ\u001ELR\u001Dလၢႆႇပေးရီးယႃး\u001ELS\u001Dလႄႇသူဝ်းတူဝ်ႇ\u001ELT\u001Dလီႉတူႇဝေးၼီးယႃး\u001ELU\u001Dလၢၵ်ႈၸိမ်ႇပၢၵ်ႈ\u001ELV\u001Dလၢတ်ႈဝီႇယႃႇ\u001ELY\u001Dလိပ်ႉပျႃး\u001EMA\u001Dမေႃႇရူဝ်ႇၵူဝ်ႇ\u001EMC\u001Dမူဝ်ႇၼႃႉၶူဝ်ႇ\u001EMD\u001Dမေႃႇတူဝ်းဝႃး\u001EME\u001Dမွၼ်ႇတေႇၼေးၵရူဝ်ႇ\u001EMF\u001Dသဵင်ႉမႃႇတိၼ်\u001EMG\u001Dမၢတ်ႈတႃႇၵၢတ်ႈသၵႃႇ\u001EMH\u001Dမူႇၵုၼ် မႃးသျႄႇ\u001EMK\u001Dမႄႇၶေႇတူဝ်းၼီးယႃးႁွင်ႇ\u001EML\u001Dမႃႇလီႇ\u001EMM\u001Dမျၢၼ်ႇမႃႇ (မိူင်းမၢၼ်ႈ)\u001EMN\u001Dမူင်ႇၵူဝ်းလီးယႃး\u001EMO\u001Dမႃႇၵၢဝ်ႈ ၼႃႈလိၼ်ဢုပ်ႉပိူင်ႇၶိုၵ်ႉတွၼ်း ၶႄႇ\u001EMP\u001Dမူႇၵုၼ် မေႇရီႇယႃႇၼႃႇ ပွတ်းႁွင်ႇ\u001EMQ\u001Dမႃးတိၼ်ႇၼိၵ်ႈ\u001EMR\u001Dမေႃႇရီႇတေးၼီးယႃး\u001EMS\u001Dမွၼ်းသိူဝ်းရၢတ်ႈ\u001EMT\u001Dမေႃးတႃႇ\u001EMU\u001Dမေႃးရီႇသႃႇ\u001EMV\u001Dမေႃႇတိပ်ႈ\u001EMW\u001Dမႃႇလႃႇဝီႇ\u001EMX\u001Dမႅၵ်ႇသီႇၵူဝ်ႇ\u001EMY\u001Dမလေးသျႃး\u001EMZ\u001Dမူဝ်ႇၸမ်းပိၵ်ႈ\u001ENA\u001Dၼႃႇမီးပီးယႃး\u001ENC\u001Dၼိဝ်းၶႄႇလီႇတူဝ်းၼီးယႃး\u001ENE\u001Dၼၢႆးၵျႃး\u001ENF\u001Dၵုၼ်ၼေႃႇၾုၵ်ႉ\u001ENG\u001Dၼၢႆႇၵျီးရီးယႃး\u001ENI\u001Dၼီႇၵႃႇရႃႇၵႂႃႇ\u001ENL\u001Dၼႄႇတႃႇလႅၼ်ႇ\u001ENO\u001Dၼေႃႇဝူၺ်း\u001ENP\u001Dၼေႇပေႃး\u001ENR\u001Dၼၢဝ်ရူး\u001ENU\u001Dၼီးဝႄႇ\u001ENZ\u001Dၼိဝ်းၸီႇလႅၼ်ႇ\u001EOM\u001Dဢူဝ်ႇမၢၼ်ႇ\u001EPA\u001Dပႃႈၼႃးမႃး\u001EPE\u001Dပေႇရူႉ\u001EPF\u001Dပေႃႇလီႇၼေးသျႃး ၶွင် ၾရၢင်ႇသဵတ်ႈ\u001EPG\u001Dပႃးပႂႃႇၼိဝ်းၵီးၼီး\u001EPH\u001Dၾီလိပ်ႈပိၼ်း\u001EPK\u001Dပႃႇၵိတ်ႈသတၼ်ႇ\u001EPL\u001Dပူဝ်ႇလႅၼ်ႇ\u001EPM\u001Dသဵင်ႉပီးယႃး လႄႈ မိၵ်ႈၵွႆႇလွၼ်ႇ\u001EPN\u001Dမူႇၵုၼ် ၽိတ်ႉၶႅၼ်ႇ\u001EPR\u001Dပေႃႇတူဝ်ႇရီးၵူဝ်း\u001EPS\u001Dၼႃႈလိၼ် ပႃႇလႅတ်ႇသတိၼ်းၼီးယႅၼ်း\u001EPT\u001Dပေႃးတူႉၵၢဝ်ႇ\u001EPW\u001Dပႃႇလၢဝ်း\u001EPY\u001Dပႃႇရႃႇၵူၺ်း\u001EQA\u001Dၶႃႇတႃႇ\u001ERE\u001Dရေႇၼီႇယၼ်ႇ\u001ERO\u001Dရူဝ်ႇမေးၼီးယႃး\u001ERS\u001Dသႃးပီးယႃး\u001ERU\u001Dရတ်ႈသျႃး\u001ERW\u001Dရဝၢၼ်းတႃႇ\u001ESA\u001Dသေႃႇတီႇဢႃႇရေးပီးယႃး\u001ESB\u001Dမူႇၵုၼ် သေႃႇလေႃႇမၼ်ႇ\u001ESC\u001Dသေးသျႄႇ\u001ESD\u001Dသူႇတၼ်ႇ\u001ESE\u001Dသုၺ်ႇတိၼ်ႇ\u001ESG\u001Dသိင်ႇၵႃႇပူဝ်ႇ\u001ESH\u001Dသဵင်ႉႁႄးလႄးၼႃႇ\u001ESI\u001Dသလူဝ်ႇဝေးၼီးယႃး\u001ESJ\u001Dသဝႃးလ်ပၢတ်ႇ လႄႈ ၸၼ်မၢႆးယႅၼ်ႇ\u001ESK\u001Dသလူဝ်ႇဝႃးၵီးယႃး\u001ESL\u001Dသီႇဢႄႇရႃႇလီႇယူၼ်ႇ\u001ESM\u001Dသၼ်းမႃႇရီႇၼေႃႇ\u001ESN\u001Dသီႇၼီႇၵႃႇ\u001ESO\u001Dသူဝ်ႇမႃႇလီႇယႃး\u001ESR\u001Dသျူးရီးၼႃႇမႄႇ\u001ESS\u001Dသူႇတၼ်ႇၸၢၼ်း\u001EST\u001Dသူၼ်ႇတူဝ်ႇမေး လႄႈ ပရိၼ်ႇသီႇပေႇ\u001ESV\u001Dဢႄႇသႃႇဝႃႇတေႃႇ\u001ESX\u001Dသိၼ်ႉမႃႇတိၼ်ႇ\u001ESY\u001Dသီးရီးယႃး\u001ESZ\u001Dဢႅတ်ႇသ